local config = {
  str_homestory_N17guide_90000101_1_dialog_content = "...",
  str_homestory_N17guide_90000101_2_dialog_content = "Hmm...",
  str_homestory_N17guide_90000101_3_dialog_content = "Vice?",
  str_homestory_N17guide_90000101_4_dialog_content = "¿Qué estás mirando?",
  str_homestory_N17guide_90000101_5_dialog_content = "Una extensión de tierra tan grande... ¡No pensé que Eraveil tuviera un lugar como este!",
  str_homestory_N17guide_90000101_6_dialog_content = "¡¿Cómo no lo notamos en todas nuestras aventuras?!",
  str_homestory_N17guide_90000101_7_dialog_content = "¿No tienes ningún recuerdo de un lugar así? Después de todo, Eraveil es tu ciudad natal...",
  str_homestory_N17guide_90000101_8_option_content = "Lo recuerdo.",
  str_homestory_N17guide_90000101_9_dialog_content = "Supongo que se podría decir que tengo una ligera impresión de ello. Las estructuras y la flora aquí se sienten bastante familiares.",
  str_homestory_N17guide_90000101_10_dialog_content = "Pero no puedo señalar dónde los he visto antes... Tal vez me equivoque.",
  str_homestory_N17guide_90000101_11_dialog_content = "Después de todo, este no es el mismo Eraveil que hemos visto antes, por lo que mis recuerdos pueden no ser tan confiables.",
  str_homestory_N17guide_90000101_12_dialog_content = "Eso tiene sentido. Entonces eras muy joven, y este lugar estaba muy bien escondido...",
  str_homestory_N17guide_90000101_13_option_content = "No recuerdo.",
  str_homestory_N17guide_90000101_14_dialog_content = "Creo que nunca he visto este lugar.",
  str_homestory_N17guide_90000101_15_dialog_content = "Los vagos recuerdos que tengo de Eraveil son de sus otras áreas. Creo que nunca vine aquí cuando era joven.",
  str_homestory_N17guide_90000101_16_dialog_content = "Eso tiene sentido, este lugar siempre estuvo muy bien escondido.",
  str_homestory_N17guide_90000101_17_dialog_content = "Eraveil es verdaderamente misterioso. Siempre nos esperan sorpresas.",
  str_homestory_N17guide_90000101_18_dialog_content = "¡No puedo esperar para explorar este lugar!<sprite=emo_aixin size=60 />",
  str_homestory_N17guide_90000101_19_dialog_content = "¿Se ha despertado de nuevo tu espíritu de equipo interior de Illumina Exploration?",
  str_homestory_N17guide_90000101_20_dialog_content = "Crick, crick.",
  str_homestory_N17guide_90000101_21_dialog_content = "¿Ah? ¿Qué es eso?",
  str_homestory_N17guide_90000101_22_dialog_content = "Parece una especie de... ¿máquina automatizada? ¿O criatura?",
  str_homestory_N17guide_90000101_23_dialog_content = "Chubb, Chubb!",
  str_homestory_N17guide_90000101_24_dialog_content = "¡Está hablando!",
  str_homestory_N17guide_90000101_25_dialog_content = "¡Bienvenido Bienvenido! ¡Cachero! ¡Cachero!",
  str_homestory_N17guide_90000101_26_dialog_content = "Se ve muy feliz. Pensé que era un dispositivo defensivo que nos marcaría como hostiles...",
  str_homestory_N17guide_90000101_27_dialog_content = "Si no me equivoco, está hecho con tecnología Caelestite. Fíjate en el material del que está hecho...",
  str_homestory_N17guide_90000101_28_dialog_content = "Las marcas también... Creo que he visto algo similar en el Colossus...",
  str_homestory_N17guide_90000101_29_dialog_content = "Pero su apariencia tonta es realmente algo, ¿eh?",
  str_homestory_N17guide_90000101_30_dialog_content = "¡¡Cachero!! ¡¡A quién llamas tonto, Chubb!!<sprite=emo_nuhuo size=60 />",
  str_homestory_N17guide_90000101_31_dialog_content = "esta enojado Tiene un temperamento enorme para una cosa tan pequeña.",
  str_homestory_N17guide_90000101_32_dialog_content = "Echemos un vistazo. ¿Podemos? ... Eh...",
  str_homestory_N17guide_90000101_33_dialog_content = "Hmm, ¿cómo debería llamarte?",
  str_homestory_N17guide_90000101_34_dialog_content = "Cachero.",
  str_homestory_N17guide_90000101_35_dialog_content = "... Chubb? ¿Te lo inventaste en el acto?",
  str_homestory_N17guide_90000101_36_dialog_content = "Sigue diciendo \"Chubb\".",
  str_homestory_N17guide_90000101_37_dialog_content = "¡Cachero! ¡Bonito nombre, Chubb!<sprite=emo_aixin size=60 />",
  str_homestory_N17guide_90000101_38_dialog_content = "¿De verdad le gusta este nombre?",
  str_homestory_N17guide_90000101_39_dialog_content = "¡Supongo que nos ha aceptado!",
  str_homestory_N17guide_90000101_40_dialog_content = "Vamos, PlayerName! ¡Echemos un vistazo!",
  str_homestory_N17guide_90000102_0_dialog_content = "Vice...",
  str_homestory_N17guide_90000102_1_dialog_content = "Ya he hablado con Chubb aquí.",
  str_homestory_N17guide_90000102_2_dialog_content = "Casi entendí lo que quería decir... ¡En realidad es muy simple!",
  str_homestory_N17guide_90000102_3_dialog_content = "¿Qué? ¿Están conversando ahora?",
  str_homestory_N17guide_90000102_4_dialog_content = "Aprendió Universese muy rápido. Incluso me dio un <color=#FFB400>hacha</color> y un <color=#FFB400>pico</color>.",
  str_homestory_N17guide_90000102_5_dialog_content = "¿Un hacha y un pico?",
  str_homestory_N17guide_90000102_6_dialog_content = "Sí. Creo que es para iniciar sesión? ¿O cavar?<sprite=emo_sikao size=60 />",
  str_homestory_N17guide_90000102_7_dialog_content = "De todos modos, creo que quiere nuestra ayuda para recopilar algunos <color=#FFB400>materiales</color>.",
  str_homestory_N17guide_90000102_8_dialog_content = "¿Quizás es para reparar los edificios aquí?",
  str_homestory_N17guide_90000102_9_dialog_content = "De todos modos, te lo dejo a ti, PlayerName. Úsalo como una oportunidad para hacer ejercicio.<sprite=emo_dianzan size=60 />",
  str_homestory_N17guide_90000102_10_dialog_content = "Ni siquiera tuve la oportunidad de negarme.<sprite=emo_xiaoku size=60 />",
  str_homestory_N17guide_90000102_11_dialog_content = "Hice un resumen de algunas de las cosas que Chubb me dijo y las registré en este <color=#FFB400>manual</color>.",
  str_homestory_N17guide_90000102_12_dialog_content = "¡Eso fue rápido!",
  str_homestory_N17guide_90000103_1_dialog_content = "¡Cachero! ¡Está reparado! ¡Hurra! ¡Cachero!<sprite=emo_yinfu size=60 />",
  str_homestory_N17guide_90000103_2_dialog_content = "¡Eso fue rápido! ¿Lo que acaba de suceder?",
  str_homestory_N17guide_90000103_3_dialog_content = "Creo que reparó el banco de trabajo en <color=#FFB400>Torre Jacinto</color>! ¡Asombroso!<sprite=emo_caitiao size=60 />",
  str_homestory_N17guide_90000103_4_dialog_content = "No es gran cosa, Chubb...<sprite=emo_guilian size=60 />",
  str_homestory_N17guide_90000103_5_dialog_content = "¿Torre Jacinto? ¿Se te ocurrió ese nombre en el acto también?",
  str_homestory_N17guide_90000103_6_dialog_content = "¡No! ¿Recuerdas la otra torre más grande en Eraveil?",
  str_homestory_N17guide_90000103_7_dialog_content = "Se ven similares, y ambas son torres. Entonces, ¡acabo de llamarlo Torre Jacinto!",
  str_homestory_N17guide_90000103_8_dialog_content = "Pero este que tenemos ante nosotros es obviamente mucho más exquisito. me pregunto para que sirve...",
  str_homestory_N17guide_90000103_9_dialog_content = "¿Por qué no lo intentas por ti mismo? ¡Cachero!",
  str_homestory_N17guide_90000103_10_dialog_content = "¡Si lo opera este Caelestite de aquí, definitivamente funcionará, Chubb!",
  str_homestory_N17guide_90000103_11_dialog_content = "¿Es eso así? ¡Entonces voy a seguir adelante!",
  str_homestory_N17guide_90000103_12_dialog_content = "PlayerName¡Chubb quiere que pruebes el banco de trabajo!",
  str_homestory_N17guide_90000103_13_dialog_content = "Parece que te ha llevado a ser el amo de este lugar.",
  str_homestory_N17guide_90000103_14_dialog_content = "Maestro...",
  str_homestory_N17guide_90000103_15_dialog_content = "Chubb, Chubb.",
  str_homestory_N17guide_90000103_16_dialog_content = "...",
  str_homestory_N17guide_90000103_17_dialog_content = "Así es, soy el dueño de este lugar ahora.",
  str_homestory_N17guide_90000103_18_dialog_content = "Lamento haberte hecho esperar tanto tiempo, Chubb.",
  str_homestory_N17guide_90000103_19_dialog_content = "¡Ya estoy de vuelta!<sprite=emo_aixin size=60 />",
  str_homestory_N17guide_90000103_20_dialog_content = "¡Estás de vuelta! ¡Cachero!<sprite=emo_yinfu size=60 />",
  str_homestory_N17guide_90000103_21_dialog_content = "Entonces, como dueño de este lugar, ¿planeas invitar a tus amigos a visitarlo?",
  str_homestory_N17guide_90000103_22_dialog_content = "¡Por supuesto! Pero, ¿dónde se quedarán todos cuando vengan?",
  str_homestory_N17guide_90000103_23_dialog_content = "Puedes usar el banco de trabajo para construir <color=#FFB400>Dormitorio Jardines</color>! ¡Cachero!",
  str_homestory_N17guide_90000103_24_dialog_content = "Existen <color=#FFB400>dormitorios</color> ¡aquí! ¡Este lugar realmente tiene un conjunto completo de instalaciones!",
  str_homestory_N17guide_90000103_25_dialog_content = "¡Vamos a intentarlo!",
  str_homestory_N17guide_90000104_1_dialog_content = "<sprite=emo_hanshui size=60 />Uf... ¡Finalmente está hecho!",
  str_homestory_N17guide_90000104_2_dialog_content = "Nunca supe que la construcción fuera tan fácil. Esperaba que tomara mucho tiempo.",
  str_homestory_N17guide_90000104_3_dialog_content = "Hablando de eso, fue lo mismo en el Coloso cuando estaba renovando habitaciones. Pude hacerlo en un instante.",
  str_homestory_N17guide_90000104_4_dialog_content = "¿Es este el poder de la tecnología? Nosotros Caelestites realmente somos asombrosos.",
  str_homestory_N17guide_90000104_5_dialog_content = "¿No es así, Vi-",
  str_homestory_N17guide_90000104_6_dialog_content = "Vice?<sprite=emo_yihuo size=60 />",
  str_homestory_N17guide_90000104_7_dialog_content = "De esta manera, PlayerName!",
  str_homestory_N17guide_90000104_8_dialog_content = "¡No puedo esperar a que los demás vengan a ver este lugar!",
  str_homestory_N17guide_90000104_9_dialog_content = "Date prisa y <color=#FFB400>invitar</color> ellos encima!",
  str_homestory_N17guide_90000104_10_dialog_content = "¡Esta bien, de acuerdo!",
  str_homestory_N17guide_90000105_1_dialog_content = "Hola, Sra. Blanc. Bienvenido a...",
  str_homestory_N17guide_90000105_2_dialog_content = "Oh...",
  str_homestory_N17guide_90000105_3_dialog_content = "... Mi <color=#FFB400>jardines de nubes</color>.",
  str_homestory_N17guide_90000105_4_dialog_content = "Ja, también eres bastante bueno inventando nombres en el acto, PlayerName.",
  str_homestory_N17guide_90000105_5_dialog_content = "Tengo un buen maestro.<sprite=emo_guilian size=60 />",
  str_homestory_N17guide_90000105_6_dialog_content = "Cloud Gardens... Impresionante, es un nombre elegante.",
  str_homestory_N17guide_90000105_7_dialog_content = "El paisaje aquí también es fantástico. Realmente te hace olvidar temporalmente todos tus problemas...",
  str_homestory_N17guide_90000105_8_dialog_content = "Gracias sinceramente por invitarme aquí, PlayerName.",
  str_homestory_N17guide_90000105_9_dialog_content = "No lo mencione, Sra. Blanc. Siempre hemos sido camaradas en nuestras aventuras, así que ahora también deberíamos cultivar juntos...",
  str_homestory_N17guide_90000105_10_dialog_content = "¡Ejem!<sprite=emo_shengqi size=60 />",
  str_homestory_N17guide_90000105_11_dialog_content = "... ¡Oh, quise decir que podemos relajarnos y disfrutar del paisaje juntos!",
  str_homestory_N17guide_90000105_12_dialog_content = "¡Ja ja! ¡Sin preocupaciones! Haré mi parte para ayudar a que Cloud Gardens prospere.",
  str_homestory_N17guide_90000105_13_dialog_content = "Aprovecharé esta oportunidad para familiarizarme con el entorno y así ser una buena guía para futuros visitantes.",
  str_homestory_N17guide_90000105_14_dialog_content = "¿Me podría presentar las otras instalaciones, PlayerName?",
  str_homestory_N17guide_90000105_15_dialog_content = "Permítame, Sra. Blanc. Chubb acaba de decirme mucho más!",
  str_homestory_N17guide_90000105_16_dialog_content = "Como <color=#FFB400>Torre Jacinto</color> se perfecciona gradualmente, podemos usar su banco de trabajo para <color=#FFB400>desbloquear aún más edificios</color>.",
  str_homestory_N17guide_90000105_17_dialog_content = "los <color=#FFB400>Jardines Dormitorios</color> que acabamos de completar puede acomodar a todos los que visitan!",
  str_homestory_N17guide_90000105_18_dialog_content = "Además de eso, tenemos <color=#FFB400>fuente de bendiciones</color>, ubicado frente a la Torre Jacinto.",
  str_homestory_N17guide_90000105_19_dialog_content = "Tiene muchas sorpresas reservadas para todos, ¡y definitivamente se convertirá en un lugar turístico popular!",
  str_homestory_N17guide_90000105_20_dialog_content = "Hay una <color=#FFB400>museo</color> también. Los raros tesoros que obtengamos se exhibirán allí...",
  str_homestory_N17guide_90000105_21_dialog_content = "¡Ay, hay más!",
  str_homestory_N17guide_90000105_22_dialog_content = "Vice, desacelerar. La Sra. Blanc no puede asimilarlo todo tan rápido...",
  str_homestory_N17guide_90000105_23_dialog_content = "Eso es cierto... Familiarizarme poco a poco experimentando el lugar en persona también es una buena idea.",
  str_homestory_N17guide_90000105_24_dialog_content = "PlayerName, ¿estás seguro de que no es porque eres tú el que no puede recordar todo?",
  str_homestory_N17guide_90000105_25_dialog_content = "<sprite=emo_xuanyun size=60 />E-Es un poco abrumador...",
  str_homestory_N17guide_90000105_26_dialog_content = "Tengo que recordar para qué sirve cada edificio, y también prepararme para recibir a todos los demás...",
  str_homestory_N17guide_90000105_27_dialog_content = "Realmente no sé qué hacer contigo. Toma, déjame darte esto. Manténlo seguro...",
  str_homestory_N17guide_90000105_28_dialog_content = "Puedes usar esto <color=#FFB400>diario</color> para grabar tu vida diaria en Cloud Gardens!",
  str_homestory_N17guide_90000105_29_dialog_content = "¡Haga registros de todo lo que sucede aquí para que no se sienta abrumado!",
  str_homestory_N17guide_90000105_30_dialog_content = "Que considerado de tu parte Vice.",
  str_homestory_N17guide_90000105_31_dialog_content = "PlayerName, si te sientes cansado, ¡sé la manera perfecta de ayudarte a relajarte!",
  str_homestory_N17guide_90000105_32_dialog_content = "¿Eh? ¿Qué es?",
  str_homestory_N17guide_90000105_33_dialog_content = "Jeje, sígueme si quieres averiguarlo!<sprite=emo_yinfu size=60 />",
  str_homestory_N17guide_90000106_0_dialog_content = "¿Eh?",
  str_homestory_N17guide_90000106_1_dialog_content = "Vice! Tu idea de relajación es...",
  str_homestory_N17guide_90000106_2_dialog_content = "¡Así es! Es <color=#FFB400>pescar</color>!<sprite=emo_caitiao size=60 />",
  str_homestory_N17guide_90000106_3_dialog_content = "No hay nada más relajante que disfrutar de los placeres de la pesca en un lugar tan hermoso.",
  str_homestory_N17guide_90000106_4_dialog_content = "(Además... los peces que pescamos pueden ser <color=#FFB400>vendido</color>.)<sprite=emo_baiyebi size=60 />",
  str_homestory_N17guide_90000106_5_dialog_content = "(Vice, prácticamente puedo oler la codicia que emana de ti.)",
  str_homestory_N17guide_90000106_6_dialog_content = "<sprite=emo_hanshui size=60 />E-Ese no es el punto... De todos modos, ¡tratemos de pescar!",
  str_homestory_N17guide_90000106_7_dialog_content = "¡Aquí están las cañas de pescar! ¡Vamos a sudar!",
  str_homestory_N17guide_90000106_8_dialog_content = "Vi una pala. ¿Para qué sirve?",
  str_homestory_N17guide_90000106_9_dialog_content = "Ah, además de pescar, planeo cavar. Quizás encuentre un tesoro.",
  str_homestory_N17guide_90000106_10_dialog_content = "Estás haciendo tus intenciones tan obvias...",
  str_homestory_N17guide_90000106_11_dialog_content = "<sprite=emo_shengqi size=60 />¿No exploramos antes también? ¡Se llama cazar tesoros! ¡A la caza del tesoro!",
  str_homestory_N17guide_90000106_12_dialog_content = "No tienes que preocuparte si te pierdes. Solo echa un vistazo a tu <color=#FFB400>mapa</color>.",
  str_homestory_N17guide_90000106_13_dialog_content = "Bien, ¡entonces pesquemos un poco primero!",
  str_homestory_N17guide_90000107_1_dialog_content = "¡Hurra! ¡La tienda está construida! ¡Este lugar está cobrando vida lentamente!",
  str_homestory_N17guide_90000107_2_dialog_content = "¡Sí, en efecto, Chubb! ¡Ya estamos listos para el negocio, Chubb!<sprite=emo_caitiao size=60 />",
  str_homestory_N17guide_90000107_3_dialog_content = "Sorprendentemente, Chubbs con diferentes apariencias están a cargo de diferentes instalaciones...",
  str_homestory_N17guide_90000107_4_dialog_content = "Ellos son tan lindos. ¡Incluso estoy considerando llevarme uno a Lumopolis conmigo!<sprite=emo_aixin size=60 />",
  str_homestory_N17guide_90000107_5_dialog_content = "Chu-Chubb!<sprite=emo_yinfu size=60 />",
  str_homestory_N17guide_90000107_6_dialog_content = "Entonces, ¿puedo empezar a ganar dinero ahora?",
  str_homestory_N17guide_90000107_7_dialog_content = "Sí, tengo toda la información que necesitas.",
  str_homestory_N17guide_90000107_8_dialog_content = "La tienda exhibirá regularmente todo tipo de <color=#FFB400>pedidos</color>. Serás recompensado por completarlos.",
  str_homestory_N17guide_90000107_9_dialog_content = "Ganar dinero sin tener que dar un paso fuera! ¡Cloud Gardens es increíble!<sprite=emo_dianzan size=60 />",
  str_homestory_N17guide_90000107_10_dialog_content = "No esperaba una tienda tan pequeña pero completamente surtida aquí...",
  str_homestory_N17guide_90000107_11_dialog_content = "Estoy aún más impresionado por Cloud Gardens ahora...",
  str_homestory_N17guide_90000107_12_dialog_content = "Darle una oportunidad, PlayerName! ¡Completemos un pedido para empezar!",
  str_homestory_N17guide_90000107_13_dialog_content = "¡Está bien!",
  str_homestory_N17guide_90000107_14_dialog_content = "En realidad, ¿por qué siempre me voy a trabajar con tanto entusiasmo?<sprite=emo_tanqi size=60 />",
  str_homestory_N17guide_90000107_15_dialog_content = "Esta es tu propia casa, PlayerName! ¡Anímate!",
  str_homestory_N17guide_90000108_0_dialog_content = "¡Listo!",
  str_homestory_N17guide_90000108_1_dialog_content = "¡Guau! ¡La recompensa es bastante buena!<sprite=emo_baiyebi size=60 />",
  str_homestory_N17guide_90000108_2_dialog_content = "¡Se siente genial ganar dinero con mis propias manos!",
  str_homestory_N17guide_90000108_3_dialog_content = "¿No hemos montado puestos y cumplido con las solicitudes antes? Incluso llevo a todos a pelear en Umbraton todos los días...",
  str_homestory_N17guide_90000108_4_dialog_content = "¡No es lo mismo! ¡Esta ha sido una experiencia totalmente nueva!",
  str_homestory_N17guide_90000108_5_dialog_content = "Hmm, me pregunto si hay más cosas en la tienda...",
  str_homestory_N17guide_90000108_6_dialog_content = "Por supuesto que los hay.",
  str_homestory_N17guide_90000108_7_dialog_content = "¿En serio? ¿Cómo sabes tanto sobre este lugar ya?<sprite=emo_yihuo size=60 />",
  str_homestory_N17guide_90000108_8_dialog_content = "Puedes probar <color=#FFB400>plantando un árbol</color>.",
  str_homestory_N17guide_90000108_9_dialog_content = "¿Los árboles aquí hay que plantarlos? Pensé que crecerían naturalmente...",
  str_homestory_N17guide_90000108_10_dialog_content = "No estoy hablando de cualquier árbol normal, sino más bien...",
  str_homestory_N17guide_90000108_11_dialog_content = "Existen estos tipos especiales de árboles llamados <color=#FFB400>Árboles únicos</color>. Incluso tienes que preparar un especial <color=#FFB400>parcela fértil</color> solo para ellos",
  str_homestory_N17guide_90000108_12_dialog_content = "¿En serio? Entonces vamos a darle una oportunidad.",
  str_homestory_N17guide_90000108_13_dialog_content = "Sabes qué, estoy un poco cansado. Regresaré a Hyacinth Tower para echar un vistazo a las cuentas.",
  str_homestory_N17guide_90000108_14_dialog_content = "Vice! ¡Plantar árboles es trabajo físico!",
  str_homestory_N17guide_90000108_15_dialog_content = "La tecnología Caelestite es muy avanzada. No hay necesidad de trabajo físico.<sprite=emo_qingsong size=60 />",
  str_homestory_N17guide_90000108_16_dialog_content = "Oye-",
  str_homestory_N17guide_90000109_1_dialog_content = "Buen trabajo, PlayerName!<sprite=emo_caitiao size=60 />",
  str_homestory_N17guide_90000109_2_dialog_content = "¡Cloud Gardens se ha vuelto tan hermoso en tan poco tiempo!",
  str_homestory_N17guide_90000109_3_dialog_content = "Chubb, Chubb, Chubb!<sprite=emo_yinfu size=60 />",
  str_homestory_N17guide_90000109_4_dialog_content = "también has trabajado duro Vice, dándome todos los detalles sobre este lugar.",
  str_homestory_N17guide_90000109_5_dialog_content = "Debe ser muy difícil entender el lenguaje de los Chubbs, ¿verdad?",
  str_homestory_N17guide_90000109_6_dialog_content = "Incluso me pediste que te ayudara. PlayerName manejar la llegada de los otros Aurorianos.",
  str_homestory_N17guide_90000109_8_dialog_content = "Así que no has estado holgazaneando, Vice.",
  str_homestory_N17guide_90000109_9_dialog_content = "¡Por supuesto que no! ¡Este es nuestro nuevo hogar! ¡Tengo que cuidarlo bien!",
  str_homestory_N17guide_90000109_10_dialog_content = "Además de eso, tengo que calcular nuestros nuevos ingresos y gastos, sin mencionar que todavía tenemos que considerar nuestros gastos regulares en el Coloso...",
